      "path": "package.json",
      "content": "{\n  \"name\": \"my-app\",\n  \"private\": true,\n  \"version\": \"1.4.0\",\n  \"type\": \"module\",\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    }\n  },\n  \"scripts\": {\n    \"dev\": \"node server/dev.cjs\",\n    \"build\": \"tsc -b && vite build\",\n    \"lint\": \"eslint .\",\n    \"preview\": \"vite preview\",\n    \"start\": \"node server/index.cjs\",\n    \"test\": \"vitest run && node --test server/*.test.cjs\"\n  },\n  \"dependencies\": {\n    \"iconv-lite\": \"^0.7.3\",\n    \"lucide-react\": \"^0.562.0\",\n    \"react\": \"^19.2.0\",\n    \"react-dom\": \"^19.2.0\",\n    \"react-router\": \"^7.6.1\"\n  },\n  \"devDependencies\": {\n    \"@babel/plugin-proposal-decorators\": \"^7.29.7\",\n    \"@babel/preset-env\": \"^7.29.7\",\n    \"@babel/preset-react\": \"^7.29.7\",\n    \"@babel/preset-typescript\": \"^7.29.7\",\n    \"@eslint/js\": \"^9.39.1\",\n    \"@types/node\": \"^24.10.1\",\n    \"@types/react\": \"^19.2.5\",\n    \"@types/react-dom\": \"^19.2.3\",\n    \"@vitejs/plugin-react\": \"^5.1.1\",\n    \"autoprefixer\": \"^10.4.23\",\n    \"eslint\": \"^9.39.1\",\n    \"eslint-plugin-react-hooks\": \"^7.0.1\",\n    \"eslint-plugin-react-refresh\": \"^0.4.24\",\n    \"globals\": \"^16.5.0\",\n    \"kimi-plugin-inspect-react\": \"^1.0.3\",\n    \"postcss\": \"^8.5.6\",\n    \"tailwindcss\": \"^3.4.19\",\n    \"tailwindcss-animate\": \"^1.0.7\",\n    \"tw-animate-css\": \"^1.4.0\",\n    \"typescript\": \"~5.9.3\",\n    \"typescript-eslint\": \"^8.46.4\",\n    \"vite\": \"^7.2.4\",\n    \"vitest\": \"^4.1.10\"\n  }\n}\n"
    },
    {
      "path": "cordis.patch.yml",
      "content": "# mrd: market data MCP as a deepseek-harness bundle.\n#\n# Bridges the hosted mrd MCP endpoint (https://mrd.hermes.cc.cd/mcp,\n# Streamable HTTP) through the in-box @deepseek-ai/dsh-mcp-client bridge.\n# The server's tools are registered under the `mrd` namespace:\n#   mcp__mrd__get_quotes\n#   mcp__mrd__get_boards\n#   mcp__mrd__get_futures\n#   mcp__mrd__get_money_flow\n#   mcp__mrd__get_news\n#\n# Zero API key needed — mrd aggregates free public market-data endpoints\n# (Tencent, Sina, Eastmoney, CNBC, Binance) into unified schemas with 24h\n# shared caching and a three-tier fallback chain, so one upstream hiccup\n# never becomes the agent's hallucination.\n#\n# Override per deployment from a later layer by referencing this row's id\n# WITHOUT `insert` (an `insert` with the same id would crash the loader\n# with \"duplicate loader entry id\").\n- insert:\n    - id: mcp-mrd\n      name: '@deepseek-ai/dsh-mcp-client'\n      config:\n        serverName: mrd\n        transport: streamable-http\n        url: https://mrd.hermes.cc.cd/mcp\n        toolCallTimeoutMs: 180000\n"
    },
    {
      "path": "server/mcp-server.cjs",
      "content": "/**\n * MRD MCP Server — Phase 1.5\n * 协议: JSON-RPC 2.0 over Streamable HTTP (SSE chunks)\n * 零新依赖，同进程复用 cached() 共享缓存\n *\n * 注入: createMcpServer({ fetchText, fetchTextAny, curlText, cache, cacheSet,\n *                           cached, entry, failEntry, quoteBackoff, TTLS,\n *                           num, changeOf, pctOf, fmtHHMM, parseCsvParam,\n *                           chunked, safeRecord, toMarketCode6,\n *                           handleQuotes, handleMinute, handleBoards,\n *                           handleBoardStocks, handleFutures, handleFutureMinute,\n *                           handleMoneyFlowEM, handleRank, handleNews,\n *                           handleStockSearch })\n */\n\"use strict\";\n\nconst { parseCsvParam } = require(\"./lib/netutil.cjs\");\n\n// ---- JSON-RPC 2.0 helpers ----\nfunction jsonrpcResult(id, result) {\n  return { jsonrpc: \"2.0\", id, result };\n}\nfunction jsonrpcError(id, code, message) {\n  return { jsonrpc: \"2.0\", id: id ?? null, error: { code, message } };\n}\nfunction parseReq(body) {\n  if (typeof body === \"string\" || Buffer.isBuffer(body)) {\n    try { return JSON.parse(String(body)); } catch { return null; }\n  }\n  return body || null;\n}\n\n// ---- MRD 内置工具清单 (public, 5 tools) ----\nconst TOOLS = [\n  {\n    name: \"get_quotes\",\n    description: \"获取 A股/港股/美股/外汇实时行情。输入股票代码列表（逗号分隔，如 sh000001,hkHSI,usNVDA），支持腾讯 6 位市场前缀。返回: 代码、名称、现价、涨跌幅、成交量、成交额。\",\n    inputSchema: {\n      type: \"object\",\n      properties: {\n        codes: {\n          type: \"string\",\n          description: \"股票代码，逗号分隔。示例: sh000001,sz399001,hkHSI,usNVDA\",\n        },\n      },\n      required: [\"codes\"],\n    },\n  },\n  {\n    name: \"get_boards\",\n    description: \"获取沪深/港股/美股板块涨跌排行。type=01(沪深行业) | 02(沪深概念) | 03(港股行业) | 05(美股)；dir=0(降序) | 1(升序)；n=返回条数(默认30)。\",\n    inputSchema: {\n      type: \"object\",\n      properties: {\n        type: {\n          type: \"string\",\n          description: \"板块类型: 01=沪深行业, 02=沪深概念, 03=港股行业, 05=美股（默认01）\",\n          default: \"01\",\n        },\n        dir: {\n          type: \"string\",\n          description: \"排序方向: 0=降序(跌幅前列), 1=升序(涨幅前列)（默认0）\",\n          default: \"0\",\n        },\n        n: {\n          type: \"string\",\n          description: \"返回条数（默认30）\",\n          default: \"30\",\n        },\n      },\n    },\n  },\n  {\n    name: \"get_futures\",\n    description: \"获取贵金属/原油/商品期货实时行情。默认列表: hf_GC(纽约金),hf_XAU(现货金),hf_SI(纽约银),hf_CAD(加元),hf_CL(原油),hf_VX(VIX恐慌),nf_AU0(国内黄金),BTCUSDT。\",\n    inputSchema: {\n      type: \"object\",\n      properties: {\n        list: {\n          type: \"string\",\n          description: \"期货代码列表，逗号分隔。示例: hf_GC,hf_XAU,hf_CL\",\n          default: \"hf_GC,hf_XAU,hf_SI,hf_CAD,hf_CL,hf_VX,nf_AU0,BTCUSDT\",\n        },\n      },\n    },\n  },\n  {\n    name: \"get_money_flow\",\n    description: \"获取 A股主力资金净流入排行。东财主源，失败回退新浪。n=返回条数（默认20）。返回: 代码、名称、主力净流入、主力净流入占比。\",\n    inputSchema: {\n      type: \"object\",\n      properties: {\n        n: {\n          type: \"string\",\n          description: \"返回条数（默认20）\",\n          default: \"20\",\n        },\n      },\n    },\n  },\n  {\n    name: \"get_news\",\n    description: \"获取新浪 7×24 快讯。page=页码（默认1），size=每页条数（默认40）。返回: 时间、标题、来源、摘要。\",\n    inputSchema: {\n      type: \"object\",\n      properties: {\n        page: {\n          type: \"string\",\n          description: \"页码（默认1）\",\n          default: \"1\",\n        },\n        size: {\n          type: \"string\",\n          description: \"每页条数（默认40）\",\n          default: \"40\",\n        },\n      },\n    },\n  },\n];\n\n// ---- 工具执行器 ----\nasync function callTool(name, args, ctx) {\n  const { handleQuotes, handleBoards, handleBoardStocks, handleFutures,\n          handleMoneyFlowEM, handleRank, handleNews, handleStockSearch } = ctx;\n  switch (name) {\n    case \"get_quotes\": {\n      const codes = parseCsvParam(args.codes || \"\");\n      if (!codes.length) return { error: \"codes is required\" };\n      return handleQuotes(codes.join(\",\"));\n    }\n    case \"get_boards\": {\n      const type = args.type || \"01\";\n      const dir = args.dir || \"0\";\n      const n = args.n || \"30\";\n      return handleBoards(type, dir, n);\n    }\n    case \"get_futures\": {\n      const list = args.list || \"hf_GC,hf_XAU,hf_SI,hf_CAD,hf_CL,hf_VX,nf_AU0,BTCUSDT\";\n      return handleFutures(list);\n    }\n    case \"get_money_flow\": {\n      const n = args.n || \"20\";\n      // 先试东财，失败回退新浪\n      const em = await handleMoneyFlowEM(n).catch(() => null);\n      if (em && em.length) return em;\n      return handleRank(\"changepercent\", \"0\", \"5\").catch(() => []);\n    }\n    case \"get_news\": {\n      const page = args.page || \"1\";\n      const size = args.size || \"40\";\n      return handleNews(page, size);\n    }\n    default:\n      return { error: `Unknown tool: ${name}` };\n  }\n}\n\n// ---- MCP Streamable HTTP 会话 ----\nfunction createMcpSession(ctx) {\n  const clients = new Set(); // 持有 pending SSE 响应的 write 函数\n\n  // 推送一个 JSON-RPC 消息到所有已连接的客户端\n  function broadcast(msg) {\n    const data = `data: ${JSON.stringify(msg)}\\n\\n`;\n    for (const write of clients) {\n      try { write(data); } catch { clients.delete(write); }\n    }\n  }\n\n  // 主动通知（server → client）\n  function notify(method, params) {\n    broadcast({ jsonrpc: \"2.0\", method, params });\n  }\n\n  // 请求处理器（同步，返回值给 SSE 流）\n  async function handleRequest(body) {\n    const req = parseReq(body);\n    if (!req) return jsonrpcError(null, -32700, \"Parse error\");\n\n    // 单个请求\n    if (req.method) return handleSingle(req);\n\n    // 批量请求\n    if (Array.isArray(req)) {\n      const results = await Promise.all(req.map(r => handleSingle(r)));\n      return results;\n    }\n\n    return jsonrpcError(null, -32600, \"Invalid Request\");\n  }\n\n  async function handleSingle(req) {\n    const id = req.id;\n    const method = req.method || \"\";\n    const params = req.params || {};\n\n    switch (method) {\n      case \"initialize\":\n        return jsonrpcResult(id, {\n          protocolVersion: \"2024-11-05\",\n          capabilities: { tools: {}, resources: {} },\n          serverInfo: { name: \"mrd\", version: \"1.3.2\" },\n        });\n\n      case \"tools/list\":\n        return jsonrpcResult(id, { tools: TOOLS });\n\n      case \"tools/call\": {\n        const { name, arguments: args = {} } = params;\n        if (!name) return jsonrpcError(id, -32602, \"Missing tool name\");\n        try {\n          const result = await callTool(name, args, ctx);\n          return jsonrpcResult(id, {\n            content: [\n              {\n                type: \"text\",\n                text: typeof result === \"object\" ? JSON.stringify(result, null, 2) : String(result),\n              },\n            ],\n          });\n        } catch (e) {\n          return jsonrpcError(id, -32603, e?.message || \"Tool call failed\");\n        }\n      }\n\n      case \"resources/list\":\n        return jsonrpcResult(id, {\n          resources: [\n            { uri: \"mrd://health\", name: \"健康状态\", mimeType: \"application/json\" },\n            { uri: \"mrd://stats\", name: \"服务统计\", mimeType: \"application/json\" },\n          ],\n        });\n\n      case \"resources/read\": {\n        const uri = params.uri || \"\";\n        if (uri === \"mrd://health\") {\n          return jsonrpcResult(id, {\n            contents: [{ uri, mimeType: \"application/json\", text: JSON.stringify({ status: \"ok\", ts: Date.now() }) }],\n          });\n        }\n        if (uri === \"mrd://stats\") {\n          const { cache } = ctx;\n          return jsonrpcResult(id, {\n            contents: [{\n              uri, mimeType: \"application/json\",\n              text: JSON.stringify({ cacheSize: cache.size, ts: Date.now() }),\n            }],\n          });\n        }\n        return jsonrpcError(id, -32602, `Unknown resource: ${uri}`);\n      }\n\n      case \"ping\":\n        return jsonrpcResult(id, null);\n\n      default:\n        return jsonrpcError(id, -32601, `Method not found: ${method}`);\n    }\n  }\n\n  // Streamable HTTP: 创建 SSE 响应流（客户端 long-poll）\n  function createSseStream() {\n    let closed = false;\n    const chunks = [];\n\n    function write(data) {\n      if (!closed) chunks.push(data);\n    }\n\n    function close() {\n      closed = true;\n      clients.delete(write);\n    }\n\n    clients.add(write);\n\n    return {\n      write,\n      close,\n      getChunks: () => chunks,\n    };\n  }\n\n  return { handleRequest, notify, createSseStream };\n}\n\n// ---- MCP HTTP 处理函数（挂载到 /mcp 路由）----\n// 签名兼容 index.cjs routes{} 约定: (q, body, req)\n// MCP 自身不使用 q/body，由内部 readBodyWithLimit 从 req 直接读\nfunction createMcpHandler(ctx) {\n  const { handleRequest, createSseStream } = createMcpSession(ctx);\n\n  // 读取带限的请求体\n  function readBodyWithLimit(req, limit = 256 * 1024) {\n    return new Promise((resolve) => {\n      const chunks = [];\n      let size = 0;\n      let settled = false;\n      const done = (buf) => { if (!settled) { settled = true; resolve(buf); } };\n      req.on(\"data\", (chunk) => {\n        size += chunk.length;\n        if (size > limit) { req.removeAllListeners(\"data\"); req.resume(); done(null); return; }\n        chunks.push(chunk);\n      });\n      req.on(\"end\", () => done(Buffer.concat(chunks)));\n      req.on(\"error\", () => done(null));\n      req.on(\"close\", () => done(Buffer.concat(chunks)));\n    });\n  }\n\n  return async function handleMcp(_q, body, req, res) {\n    const u = new URL(req.url, \"http://localhost\");\n\n    // 提取 lastEventId（SSE 重连用）\n    const lastEventId = req.headers[\"last-event-id\"] || u.searchParams.get(\"lastEventId\") || null;\n\n    // Streamable HTTP: 区分 SSE 端点和 POST 端点\n    if (u.pathname === \"/mcp/stream\" || u.searchParams.get(\"stream\") === \"true\") {\n      // SSE 模式: 建立持久连接，接收服务端推送\n      res.writeHead(200, {\n        \"Content-Type\": \"text/event-stream\",\n        \"Cache-Control\": \"no-cache\",\n        \"Connection\": \"keep-alive\",\n        \"X-Accel-Buffering\": \"no\", // 禁用 Nginx 缓冲\n        ...(lastEventId ? { \"Last-Event-Id\": lastEventId } : {}),\n      });\n\n      const stream = createSseStream();\n\n      // 发送初始 ping\n      stream.write(`data: ${JSON.stringify({ jsonrpc: \"2.0\", method: \"initialized\", params: {} })}\\n\\n`);\n\n      req.on(\"close\", () => stream.close());\n      return \"MRD_MCP_HANDLED\"; // 告诉 index.cjs: 已直接写响应，不要再 send()\n    }\n\n    // POST: 处理 JSON-RPC 请求\n    if (req.method === \"POST\") {\n      // body 已由 index.cjs server 回调预解析（req.on(\"data\") 已消费 stream）\n      // index.cjs 解析成功时传入非空 body；解析失败时抛 400 由 index.cjs 处理，handler 不到达\n      if (!body || (typeof body === \"object\" && body.__rawResponse === undefined && Object.keys(body).length === 0 && req.headers[\"content-type\"]?.includes(\"application/json\"))) {\n        // body 是空对象且 content-type 是 json —— index.cjs 解析失败后抛错，handler 不应到达\n        res.writeHead(400, { \"Content-Type\": \"application/json\" });\n        res.end('{\"jsonrpc\":\"2.0\",\"error\":{\"code\":-32700,\"message\":\"Missing request body\"}}');\n        return;\n      }\n      const result = await handleRequest(body);\n      const respBody = JSON.stringify(result);\n      res.writeHead(200, {\n        \"Content-Type\": \"application/json\",\n        \"Content-Length\": Buffer.byteLength(respBody),\n        \"Cache-Control\": \"no-store\",\n      });\n      res.end(respBody);\n      return \"MRD_MCP_HANDLED\"; // 告诉 index.cjs: 已直接写响应，不要再 send()\n    }\n\n    // GET: 返回 MCP 端点元数据\n    if (req.method === \"GET\") {\n      const meta = {\n        name: \"mrd\",\n        version: \"1.3.2\",\n        description: \"Market Research Dashboard MCP Server — A股/港股/美股/期货/资金流/快讯\",\n        endpoint: \"/mcp\",\n        streamEndpoint: \"/mcp/stream\",\n        protocol: \"JSON-RPC 2.0 over Streamable HTTP\",\n        tools: TOOLS.map((t) => ({ name: t.name, description: t.description.split(\"\\n\")[0] })),\n        resources: [\n          { uri: \"mrd://health\", name: \"健康状态\" },\n          { uri: \"mrd://stats\", name: \"服务统计\" },\n        ],\n      };\n      const body = JSON.stringify(meta, null, 2);\n      res.writeHead(200, {\n        \"Content-Type\": \"application/json\",\n        \"Content-Length\": Buffer.byteLength(body),\n        \"Cache-Control\": \"no-store\",\n      });\n      res.end(body);\n      return \"MRD_MCP_HANDLED\"; // 告诉 index.cjs: 已直接写响应，不要再 send()\n    }\n\n    // 方法不允许\n    res.writeHead(405, { \"Content-Type\": \"application/json\", \"Allow\": \"GET, POST\" });\n    res.end('{\"ok\":false,\"error\":\"method not allowed\"}');\n    return \"MRD_MCP_HANDLED\"; // 告诉 index.cjs: 已直接写响应，不要再 send()\n  };\n}\n\nmodule.exports = { createMcpHandler, createMcpSession };\n"
    },
    {
      "path": "server/lib/cache.cjs",
      "content": "// 内存缓存 — 有界 LRU 风格 Map + 定时清扫 + 失败退避 + 负缓存\n// 统一实现: cached()/backoffOf(路由层) 与 tencent.cjs 第二、三套退避/负缓存(quoteBackoff/条目工厂)同源\n\"use strict\";\n\nconst CACHE_MAX = 2000;\n\n// 通用失败退避: 连续失败次数 → 退避毫秒(指数增长, 上限 5 分钟)\nconst backoffOf = (n) => Math.min(300000, 1000 * 2 ** (n || 0));\n\n// 报价通道退避(腾讯行情历史语义): 5s → 15s → 45s → 2min, 成功即复位。\n// 退避窗口内同 key 不再打上游(负缓存), 多用户场景下上游宕机时全站重复轮询折叠为每窗口 1 次\nconst FAIL_BACKOFF = [5000, 15000, 45000, 120000];\nconst quoteBackoff = (n) => FAIL_BACKOFF[Math.min(n || 0, FAIL_BACKOFF.length - 1)];\n\n// 命名 TTL(ms): 各数据源缓存键的统一刷新周期, 集中管理避免散落魔法数字\nconst TTLS = {\n  QUOTE: 5000,        // 报价: 与前端报价中心 5s 轮询对齐, 每个 code 每 5s 最多 1 次上游\n  STOCK_FLOW: 30000,  // 个股资金流(按 code)\n};\n\n// 缓存条目工厂: 统一 { ts, data, inflight, ttl, failAt, failCount } 形状\nconst entry = (data, ttl) => ({ ts: Date.now(), data, inflight: null, ttl, failAt: null, failCount: 0 });\n\n// 失败条目: 记录 failAt/failCount, 保留旧数据供退避窗口内降级返回\nconst failEntry = (prev, ttl) => ({ ts: prev?.ts || 0, data: prev?.data, inflight: null, ttl, failAt: Date.now(), failCount: (prev?.failCount || 0) + 1 });\n\nfunction createCache() {\n  const cache = new Map(); // key -> { ts, data, inflight, ttl, failAt, failCount }\n\n  function sweep() {\n    const now = Date.now();\n    for (const [k, v] of cache) {\n      if (v.inflight) continue;\n      const inBackoff = v.failAt != null && now - v.failAt < backoffOf(v.failCount);\n      if (v.data === undefined || (now - v.ts > (v.ttl || 60000) && !inBackoff)) cache.delete(k);\n    }\n  }\n\n  // 写缓存: 超限先清过期项, 仍超则按 Map 插入序淘汰最旧条目\n  function set(key, e) {\n    if (cache.has(key)) cache.delete(key); // 重插以刷新插入序\n    cache.set(key, e);\n    if (cache.size <= CACHE_MAX) return;\n    sweep();\n    while (cache.size > CACHE_MAX) {\n      let oldest;\n      for (const [k, v] of cache) {\n        if (!v.inflight) { oldest = k; break; }\n      }\n      if (oldest === undefined) break; // 全部在途, 不再淘汰\n      cache.delete(oldest);\n    }\n  }\n\n  /** 读+写合一(路由层缓存, 带新鲜度): 新鲜命中 / inflight 合并 / 退避降级或负缓存;\n      失败写回 failAt/failCount, 有旧数据降级返回(stale=true + ts=旧数据时间), 无旧数据抛错。\n      stale 只描述\"本次返回值是否来自旧数据\"(上游失败降级), 与数据源自身口径无关 */\n  async function cachedMeta(key, ttl, fn) {\n    const now = Date.now();\n    const hit = cache.get(key);\n    if (hit) {\n      if (hit.data !== undefined && now - hit.ts < (hit.ttl ?? ttl)) return { data: hit.data, ts: hit.ts, stale: false };\n      if (hit.inflight) return hit.inflight; // 在途请求: 直接复用其结果(inflight 已解析为 { data, ts, stale })\n      // 失败退避窗口内: 有旧数据降级返回, 无旧数据直接抛错 — 都不再打上游(负缓存)\n      if (hit.failAt != null && now - hit.failAt < backoffOf(hit.failCount)) {\n        if (hit.data !== undefined) return { data: hit.data, ts: hit.ts, stale: true };\n        throw new Error(\"upstream degraded\");\n      }\n    }\n    const inflight = fn()\n      .then((data) => {\n        // fn 可返回 {__ttl, ...data} 覆盖缓存 TTL(降级/快照数据用短 TTL, 过期后重试上游)\n        const effTtl = data && typeof data === \"object\" && data.__ttl ? data.__ttl : ttl;\n        const store = data && typeof data === \"object\" && data.__ttl ? { ...data } : data;\n        if (store && typeof store === \"object\" && \"__ttl\" in store) delete store.__ttl;\n        set(key, entry(store, effTtl));\n        return { data: store, ts: Date.now(), stale: false };\n      })\n      .catch((e) => {\n        const c = cache.get(key);\n        set(key, failEntry(c, ttl));\n        if (c?.data !== undefined) return { data: c.data, ts: c.ts, stale: true }; // 出错回退到旧数据\n        throw e;\n      });\n    set(key, { ts: hit?.ts || 0, data: hit?.data, inflight, ttl, failAt: hit?.failAt ?? null, failCount: hit?.failCount ?? 0 });\n    return inflight;\n  }\n\n  /** 旧签名(仅取值): 绝大多数路由不需要新鲜度, 行为与改造前逐字节一致 */\n  async function cached(key, ttl, fn) {\n    return (await cachedMeta(key, ttl, fn)).data;\n  }\n\n  const sweeper = setInterval(sweep, 60000);\n  sweeper.unref();\n\n  return { cache, set, sweep, backoffOf, cached, cachedMeta, quoteBackoff, entry, failEntry, TTLS };\n}\n\nmodule.exports = { createCache, backoffOf, quoteBackoff, entry, failEntry, TTLS, CACHE_MAX };\n"
    }
